{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Weincluded studies evaluating the accuracy of commercially available Ag-RDTs to establish a diagnosis of SARS-CoV-2 infection, against reverse transcription polymerase chain reaction (RT-PCR) or cell culture as reference standard. We included all study populations irrespective of age, presence of symptoms, or study location. We considered cohort studies, nested cohort studies, case-control or cross-sectional studies, and randomized studies.",
      "reason": "The manuscript explicitly specifies the study characteristics, including the intervention (Ag-RDTs), the reference standard (RT-PCR or cell culture), the population (all ages, symptoms, locations), and the eligible study designs."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "We included both peer-reviewed publications and preprints.",
      "reason": "The manuscript specifies the inclusion of both peer-reviewed publications and preprints. While language is not explicitly stated as an exclusion criterion in the methods text, the results section (text_19) notes that all studies were written in English except for two, implying English was the primary language of inclusion."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not report excluding studies specifically because outcomes were not measured versus not reported; the exclusion criteria provided in the text and PRISMA flow diagram (text_19, figure_3) focus on study design, population, and intervention characteristics."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "Thus, while we extracted the data for both kinds of studies, we only considered data from clinical accuracy studies as eligible for the meta-analysis. Separately, we summarized the results of analytical studies and compared them with the results of the meta-analysis for individual tests.",
      "reason": "The manuscript specifies how studies were grouped for synthesis: clinical accuracy studies were meta-analyzed, while analytical accuracy studies were summarized separately."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Also, publications with a population size smaller than 10 were excluded. Although the size threshold of 10 is arbitrary, such small studies are more likely to give unreliable estimates of sensitivity and specificity.",
      "reason": "The authors provide a rationale for the exclusion of studies with a population size smaller than 10."
    }
  ],
  "confidence": 100
}

